def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def get_pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            try:
                return int(v[0]), int(v[1])
            except Exception:
                return default
        return default

    def step_towards(a, b):
        ax, ay = a
        bx, by = b
        return [clamp_step(bx - ax), clamp_step(by - ay)]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    env = observation.get("environment_name", "resource_collection")
    sx, sy = get_pos(observation.get("self_position"))
    ox, oy = get_pos(observation.get("opponent_position"), (sx, sy))
    w = observation.get("grid_width", 0)
    h = observation.get("grid_height", 0)

    obstacles = observation.get("obstacles") or observation.get("walls") or []
    blocked = set()
    for p in obstacles:
        x, y = get_pos(p, None)
        if x is not None:
            blocked.add((x, y))

    def legal(move):
        nx, ny = sx + move[0], sy + move[1]
        if nx < 0 or ny < 0:
            return False
        if w and nx >= w:
            return False
        if h and ny >= h:
            return False
        if (nx, ny) in blocked:
            return False
        return True

    def choose_best(targets, prefer_far_from_opponent=False, avoid_opponent=False):
        best = None
        best_score = None
        for t in targets:
            tx, ty = get_pos(t, None)
            if tx is None:
                continue
            move = step_towards((sx, sy), (tx, ty))
            if not legal(move):
                alt_moves = [
                    [move[0], 0],
                    [0, move[1]],
                    [move[0], -move[1]],
                    [-move[0], move[1]],
                    [0, 0],
                ]
                found = None
                for m in alt_moves:
                    if m[0] < -1 or m[0] > 1 or m[1] < -1 or m[1] > 1:
                        continue
                    if legal(m):
                        found = m
                        break
                if found is None:
                    continue
                move = found
            nx, ny = sx + move[0], sy + move[1]
            score = manhattan((nx, ny), (tx, ty))
            if avoid_opponent:
                score -= manhattan((nx, ny), (ox, oy))
            if prefer_far_from_opponent:
                score += max(0, 4 - manhattan((nx, ny), (ox, oy)))
            key = (score, -manhattan((tx, ty), (sx, sy)), -tx, -ty)
            if best is None or key < best_score:
                best = move
                best_score = key
        if best is not None:
            return best
        return [0, 0]

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            move = step_towards((sx, sy), (ox, oy))
            if legal(move):
                return move
            for m in ([move[0], 0], [0, move[1]], [move[0], -move[1]], [-move[0], move[1]], [0, 0]):
                if -1 <= m[0] <= 1 and -1 <= m[1] <= 1 and legal(m):
                    return m
            return [0, 0]
        corners = [(0, 0)]
        if w and h:
            corners = [(0, 0), (0, h - 1), (w - 1, 0), (w - 1, h - 1)]
        target = None
        best_dist = None
        for c in corners:
            d = manhattan(c, (ox, oy))
            if best_dist is None or d > best_dist:
                best_dist = d
                target = c
        if target is None:
            target = (0, 0)
        move = step_towards((sx, sy), target)
        if legal(move):
            return move
        for m in ([move[0], 0], [0, move[1]], [0, 0], [-move[0], move[1]], [move[0], -move[1]]):
            if -1 <= m[0] <= 1 and -1 <= m[1] <= 1 and legal(m):
                return m
        return [0, 0]

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier_cells") or []
        move = choose_best(targets, prefer_far_from_opponent=False, avoid_opponent=True)
        if move != [0, 0]:
            return move
        # When no targets or blocked, drift toward center / away from opponent
        cx = (w - 1) // 2 if w else sx
        cy = (h - 1) // 2 if h else sy
        if manhattan((sx, sy), (ox, oy)) <= 2:
            move = step_towards((sx, sy), (sx + clamp_step(sx - ox), sy + clamp_step(sy - oy)))
        else:
            move = step_towards((sx, sy), (cx, cy))
        if legal(move):
            return move
        for m in ([0, 0], [move[0], 0], [0, move[1]], [-move[0], -move[1]]):
            if -1 <= m[0] <= 1 and -1 <= m[1] <= 1 and legal(m):
                return m
        return [0, 0]

    resources = observation.get("resources") or observation.get("resource_positions") or []
    if resources:
        # Prefer closer resources, but break ties by moving away from opponent if nearby.
        best = None
        best_key = None
        for r in resources:
