            if rx is None:
                continue
            move = step_towards((sx, sy), (rx, ry))
            if not legal(move):
                alt = None
                for m in ([move[0], 0], [0, move[1]], [0, 0], [-move[0], move[1]], [move[0], -move[1]]):
                    if -1 <= m[0] <= 1 and -1 <= m[1] <= 1 and legal(m):
